#include <iostream>
#include <array>
#include <climits>
#include <cassert>
static_assert(CHAR_BIT==8,"This exercise requires 8-bit bytes");
struct Markers {
    std::array<unsigned char,4000> seen{};
    std::array<unsigned char,4000> repeated{};
    // 번호를 먼저 검증하고 나서 비트 위치를 구합니다.
    bool add(int x) {
        if(x<1||x>32000) return false;
        unsigned i=static_cast<unsigned>(x-1), byte=i/8, bit=i%8;
        unsigned char mask=static_cast<unsigned char>(1u<<bit);
        if((seen[byte]&mask)!=0) repeated[byte]|=mask;
        seen[byte]|=mask;
        return true;
    }
    bool duplicate(int x) const {
        unsigned i=static_cast<unsigned>(x-1);
        return (repeated[i/8] & (1u<<(i%8)))!=0;
    }
};
int main() {
    Markers m;
    long long x;
    // 정상 입력은 공백으로 구분한 정수들의 열이며 EOF에서 끝납니다.
    while(true) {
        std::cin >> std::ws;
        if(std::cin.peek()==std::char_traits<char>::eof()) break;
        if(!(std::cin>>x)||x<1||x>32000) return 1;
        m.add(static_cast<int>(x));
    }
    for(int value=1;value<=32000;++value)
        if(m.duplicate(value)) std::cout<<value<<'\n';
}
